<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sqlite3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .data/piwi.db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.backup &#39;.data/piwi-backup.db&#39;&quot;</span></span>
